import React, { useState, useEffect, useContext } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { listings } from '../list'; // Adjust the path as necessary
import { SearchContext } from '../context/SearchContext'; // Import the context

function SearchResults() {
  const location = useLocation();
  const searchParams = new URLSearchParams(location.search);
  const query = searchParams.get('query')?.toLowerCase() || '';
  const initialLocation = searchParams.get('location')?.toLowerCase() || 'all';

  const { selectedLocation, setSelectedLocation } = useContext(SearchContext); // Use context

  // State for filters
  const [tempLocation, setTempLocation] = useState(selectedLocation);
  const [tempCondition, setTempCondition] = useState('all');
  const [selectedCondition, setSelectedCondition] = useState('all');
  const [appliedFilters, setAppliedFilters] = useState({
    location: initialLocation,
    condition: 'all',
  });

  const navigate = useNavigate();

  useEffect(() => {
    setTempLocation(selectedLocation);
  }, [selectedLocation]);

  // Helper function to flatten listings
  const flattenListings = () => {
    const flattened = [];

    Object.entries(listings).forEach(([category, items]) => {
      if (Array.isArray(items)) {
        flattened.push(
          ...items.map((item) => ({ ...item, category }))
        );
      } else {
        Object.entries(items).forEach(([subcategory, subitems]) => {
          flattened.push(
            ...subitems.map((item) => ({ ...item, category, subcategory }))
          );
        });
      }
    });

    return flattened;
  };

  // Apply filters when "Apply Filters" button is clicked
  const handleApplyFilters = () => {
    setSelectedLocation(tempLocation);
    setSelectedCondition(tempCondition);
    setAppliedFilters({
      location: tempLocation,
      condition: tempCondition,
    });
  };

  // Flatten and filter listings based on search query and applied filters
  const filteredListings = flattenListings().filter(
    (item) =>
      (appliedFilters.location === 'all' || item.location.toLowerCase() === appliedFilters.location.toLowerCase()) &&
      (appliedFilters.condition === 'all' || item.condition.toLowerCase() === appliedFilters.condition.toLowerCase()) &&
      (item.title.toLowerCase().includes(query) ||
        item.location.toLowerCase().includes(query) ||
        (item.category && item.category.toLowerCase().includes(query)) ||
        (item.subcategory && item.subcategory.toLowerCase().includes(query)))
  );

  return (
    <div className="container mx-auto px-4 py-6 flex flex-col md:flex-row">
      {/* Sidebar Filter Section */}
      <div className="w-full md:w-1/4 md:pr-4 mb-6 md:mb-0">
        <div className="bg-white border rounded-lg shadow-md p-4">
          <h2 className="text-lg font-semibold mb-4">Filter</h2>

          {/* Location Filter */}
          <div className="mb-4">
            <label className="block text-sm font-medium mb-2">Location</label>
            <select
              className="w-full border-gray-300 rounded-md"
              value={tempLocation}
              onChange={(e) => setTempLocation(e.target.value)}
            >
              <option value="all">All Locations</option>
              <option value="Lefkosia">Lefkosia</option>
              <option value="Magusa">Magusa</option>
              <option value="Girne">Girne</option>
              <option value="Lefke">Lefke</option>
              <option value="Iskele">Iskele</option>
            </select>
          </div>

          {/* Condition Filter */}
          <div className="mb-4">
            <label className="block text-sm font-medium mb-2">Condition</label>
            <div className="space-y-2">
              <label className="flex items-center">
                <input
                  type="radio"
                  name="condition"
                  value="all"
                  checked={tempCondition === 'all'}
                  onChange={(e) => setTempCondition(e.target.value)}
                  className="mr-2"
                />
                All
              </label>
              <label className="flex items-center">
                <input
                  type="radio"
                  name="condition"
                  value="new"
                  checked={tempCondition === 'new'}
                  onChange={(e) => setTempCondition(e.target.value)}
                  className="mr-2"
                />
                New
              </label>
              <label className="flex items-center">
                <input
                  type="radio"
                  name="condition"
                  value="used"
                  checked={tempCondition === 'used'}
                  onChange={(e) => setTempCondition(e.target.value)}
                  className="mr-2"
                />
                Used
              </label>
            </div>
          </div>

          <button
            className="bg-red-500 text-white w-full py-2 rounded-md mt-4 hover:bg-red-600"
            onClick={handleApplyFilters}
          >
            Apply Filters
          </button>
        </div>
      </div>

      {/* Results Section */}
      <div className="w-full md:w-3/4">
        <h1 className="text-2xl font-semibold mb-6">Search Results for "{query}"</h1>
        {filteredListings.length > 0 ? (
          <div className="space-y-4">
            {filteredListings.map((listing) => (
              <div
                key={listing.id}
                className="flex flex-col md:flex-row bg-white border rounded-lg shadow-md overflow-hidden cursor-pointer"
                onClick={() => navigate(`/listing/${listing.id}`, { state: { listing } })}
              >
                {/* Image Section */}
                <div className="w-full md:w-1/3">
                  <img
                    src={listing.images[0]}
                    alt={listing.title}
                    className="w-full h-48 md:h-full object-cover"
                  />
                </div>

                {/* Content Section */}
                <div className="w-full md:w-2/3 p-4 flex flex-col justify-between">
                  <div>
                    <h2 className="text-lg font-medium">{listing.title}</h2>
                    <p className="text-gray-600 text-base mt-2">{listing.Message}</p>
                    <p className="text-gray-600 font-semibold text-xl mt-2">
                      {listing.price}
                    </p>
                    <p className="text-gray-500 text-sm">{listing.location}</p>
                    <p className="text-sm text-gray-700 mt-2">{listing.added}</p>
                    <p className="text-sm text-gray-700">Year: {listing.year}</p>
                  </div>
                  <div className="flex space-x-4 mt-4">
                    <button className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600">
                      Call
                    </button>
                    <button className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600">
                      WhatsApp
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-gray-500">No results found for "{query}".</p>
        )}
      </div>
    </div>
  );
}

export default SearchResults;
